FX = {}


def build_cast():
    build_human(YOU, YOU_SPEC, 'Chars')
    for nm, (C, sp) in HEROES.items():
        build_human(nm, sp, C, hair_particles_on=nm in ('sci1', 'sci2'))
    for nm in [YOU] + list(HEROES):
        park(nm)
    build_crowd_variants()


STAND_VARS, SIT_VARS, REPORTER_VARS, COAT_VARS = [], [], [], []


def build_crowd_variants():
    """Six lab-coat variants (skin, hair, height) baked once and instanced as the facility's staff."""
    template_collection('PeopleT')
    rng = np.random.default_rng(17)
    skins = list(SKINS)
    hairs = ['hair_black', 'hair_brown', 'hair_dark', 'hair_blonde', 'hair_auburn', 'hair_grey']
    styles = ['long', 'bob', 'ponytail', 'bun', 'long']
    for i in range(6):
        spec = dict(sex='f', skin=skins[int(rng.integers(len(skins)))], hair=hairs[int(rng.integers(len(hairs)))],
                    hstyle=styles[int(rng.integers(len(styles)))], top='labcoat', topmat='labcoat_white', bottom='trousers',
                    bottommat=('trousers_black', 'trousers_navy', 'jeans_blue')[i % 3], shoes=('shoe_black', 'shoe_brown')[i % 2],
                    iris='brown', height=rng.uniform(0.92, 1.0), subdiv=0, girth=rng.uniform(0.95, 1.1))
        nm = f'pv{i:02d}'
        build_human(nm, spec, 'Booth', hair_particles_on=False)
        bpy.context.view_layer.update()
        P = dict(look=(0, 0), lid=0.35, smile=0.0, shR=(0, 6, 0), shL=(0, 6, 0), elR=12, elL=12, nod=rng.normal(4, 4))
        COAT_VARS.append(bake_human(nm, 'PeopleT', P))
    for i, ob in enumerate(COAT_VARS):
        ob.name = f'PV_{i:02d}'


def people(name, pts, yaws, kinds, collection, seed=0):
    """Instance baked people: kinds 'stand' / 'sit' / 'rep' per point (an index into the template collection)."""
    rng = np.random.default_rng(seed)
    allv = STAND_VARS + SIT_VARS + REPORTER_VARS + COAT_VARS
    base = {'stand': 0, 'sit': len(STAND_VARS), 'rep': len(STAND_VARS) + len(SIT_VARS), 'coat': len(STAND_VARS) + len(SIT_VARS) + len(REPORTER_VARS)}
    cnt = {'stand': len(STAND_VARS), 'sit': len(SIT_VARS), 'rep': max(1, len(REPORTER_VARS)), 'coat': len(COAT_VARS)}
    var = [base[k] + int(rng.integers(cnt[k])) for k in kinds]
    # the instancer picks templates in the template collection's order, which is name order
    order = sorted(range(len(allv)), key=lambda i: allv[i].name)
    remap = {old: new for new, old in enumerate(order)}
    var = [remap[v] for v in var]
    return instancer(name, pts, var, yaws, rng.uniform(0.97, 1.03, len(pts)), 'PeopleT', collection)


def build_crowds():
    rng = np.random.default_rng(23)
    P, Y = [], []
    for k, (x, y) in enumerate(SETS['faci_consoles']):
        if k == 2:                                  # the comparison console belongs to the two scientists
            continue
        for dx in (-1.0, 1.0):
            P.append((FACI.x + x + dx, FACI.y + y - 0.75, 0.0))
            Y.append(rng.normal(0, 0.2))
    cols = [(x, y) for x in np.arange(-24, 25, 8.0) for y in (-8, 10, 28, 46)]
    k = 0
    while k < 34:
        x, y = rng.uniform(-25, 9), rng.uniform(-6, 31)
        if (min((x - cx) ** 2 + (y - cy) ** 2 for cx, cy in cols) < 1.4 or x * x + (y - 22) ** 2 < 40
                or (-6 < x < 6 and 8 < y < 21) or (-10 < x < -2 and 30 < y < 36)):
            continue
        P.append((FACI.x + x, FACI.y + y, 0.0))
        Y.append(rng.uniform(-3.1, 3.1))
        k += 1
    # watchers in front of the giant display (scene 3)
    for x in np.arange(-9, 10, 1.6):
        for y in (42.4, 43.9):
            if rng.random() < 0.25:
                continue
            P.append((FACI.x + x + rng.uniform(-0.3, 0.3), FACI.y + y + rng.uniform(-0.3, 0.3), 0.0))
            Y.append(rng.normal(0, 0.15))
    people('FaciStaff', P, Y, ['coat'] * len(P), 'Faci', 5)


def face_pt(name):
    return jmat(CH[name]['J']['neck']) @ (HC2 + Vector((0, 0.09, EYE_Z)))


def eyes_pt(name):
    return jmat(CH[name]['J']['neck']) @ (HC2 + Vector((0, 0.085, EYE_Z)))


def hide_phone():
    """(Part 1's phone prop is not in this film.)"""
    if 'phone' in SETS:
        SETS['phone'].location = (0, 0, -500)


# --- choreography ----------------------------------------------------------------------------------------------------
SCI_DESK = DESK + Vector((0.0, -0.75, 0.0))          # where she stands at her workstation (facing +Y)
SCI_TWIST = FACI + Vector((-1.5, 16.6, 0.0))         # scenes 4-5: beside the desk, facing him
GROUP = {'sci2': FACI + Vector((1.3, 17.4, 0.0)), 'dir': FACI + Vector((-2.6, 17.2, 0.0))}


def stand(name, loc, yaw, t, face, look=None, seed=0.0, head=0.6, extra=None):
    P = merge(dict(loc=tuple(loc), yaw=yaw), idle(t, seed), face, extra or {})
    pose(name, P)
    if look is not None:
        P.update(look_at(name, look, head=head))
        pose(name, P)
    return P


def you_face():
    return face_pt(YOU)


def chor3(t, shot):
    hide_phone()
    hero_eye = HERO + Vector((0, 0, 1.72))
    if shot in ('monitor', 'eyes', 'look'):
        # she studies the monitor, then turns slowly to look at him behind her
        u = smooth(ramp(t, 2.75, 3.8))
        f = blend_face(BUSY, STUNNED, ramp(t, 0.6, 1.8))
        f = blend_face(f, UNEASY, u)
        mon = DESK + Vector((0, 0.08, 1.95))
        stand('sci1', SCI_DESK, -165 * u, t, f, look=mon if u < 0.45 else hero_eye, seed=2.0, head=0.75)
        stand(YOU, HERO, 0, t, PUZZLED, look=SCI_DESK + Vector((0, 0, 1.6)))
    elif shot in ('compare',):
        c = FACI + Vector((-6.0, 34.3, 1.35))
        S = stand('sci1', FACI + Vector((-6.55, 33.25, 0)), -8, t, blend_face(BUSY, STUNNED, ramp(t, 9.0, 9.6)), seed=2.0)
        S['shR'], S['elR'] = reach('sci1', 'R', c + Vector((-0.15 + 0.2 * smooth(ramp(t, 8.5, 9.2)), -0.6, -0.3)))
        S.update(look_at('sci1', c, head=0.6))
        pose('sci1', S)
        stand('sci2', FACI + Vector((-5.35, 33.3, 0)), 12, t, blend_face(BUSY, AWE_F, ramp(t, 9.1, 9.7)), look=c, seed=4.0)
        if t > 9.3:
            stand('sci2', FACI + Vector((-5.35, 33.3, 0)), 12 + 40 * smooth(ramp(t, 9.3, 9.9)), t, AWE_F,
                  look=FACI + Vector((-6.55, 33.25, 1.6)), seed=4.0)
    elif shot == 'watch':
        wall = FACI + Vector((0, 61.6, 9.0))
        stand('sci1', FACI + Vector((-0.6, 47.8, 0)), 0, t, blend_face(STUNNED, AWE_F, ramp(t, 15.2, 16.2)), look=wall, seed=2.0,
              extra=dict(loc=tuple(FACI + Vector((-0.6, 47.8 + 0.35 * smooth(ramp(t, 15.4, 16.4)), 0)))))
        stand('sci2', FACI + Vector((1.1, 47.3, 0)), 8, t, AWE_F, look=wall, seed=4.0)
        D = stand('dir', FACI + Vector((-2.3, 47.0, 0)), -6, t, STUNNED, look=wall, seed=6.0)
        if t > 15.6:      # a hand rises to her mouth
            D['shR'], D['elR'] = reach('dir', 'R', face_pt('dir') + Vector((0.02, 0.12, -0.07)))
            pose('dir', D)
    elif shot in ('inside', 'turn', 'face', 'symbol', 'step', 'push'):
        # he stands where the signal comes out of him; the scientists turn, the lead scientist backs away
        stand(YOU, HERO, 0 if shot in ('inside',) else -8, t,
              blend_face(PUZZLED, FEAR_F, ramp(t, 22.0, 26.5)), seed=1.0,
              look=(HERO + Vector((0, 0.6, 0.0)) if shot == 'inside' and t < 22.3 else
                    (DESK + Vector((0, 0.08, 1.95)) if shot == 'symbol' else SCI_TWIST + Vector((0, 0, 1.6)))),
              extra=dict(nod=10.0 * (1 - ramp(t, 21.8, 22.6))))
        u = smooth(ramp(t, 22.95, 23.8))
        back = smooth(ramp(t, 26.7, 27.4))
        loc = SCI_TWIST + Vector((0, 0.65 * back, 0))
        stand('sci1', loc, 15 + 165 * u, t, blend_face(STUNNED, FEAR_F, ramp(t, 23.4, 26.8)),
              look=you_face() if u > 0.4 else FACI + Vector((0, 40, 3)), seed=2.0, head=0.7)
        for k, (nm, p) in enumerate(GROUP.items()):
            uk = smooth(ramp(t, 23.05 + 0.2 * k, 23.9 + 0.2 * k))
            stand(nm, p, (-10 if nm == 'sci2' else 10) + (170 if nm == 'sci2' else -170) * uk, t,
                  blend_face(BUSY, STUNNED, uk), look=you_face() if uk > 0.4 else FACI + Vector((0, 40, 3)), seed=3.0 + k)


CHOR = {nm: chor3 for nm in ('monitor', 'eyes', 'look', 'compare', 'watch', 'inside', 'turn', 'face', 'symbol', 'step', 'push')}
CHOR_PEOPLE = {}

# ============================================================================
# Cameras (one rig per shot; every shot moves) and everything that moves on its own each frame
# ============================================================================
def V3(*a):
    return Vector(a)


def fwd(yaw):
    """The horizontal direction a character with this yaw (degrees) faces."""
    return V3(-math.sin(R(yaw)), math.cos(R(yaw)), 0)


def landmark(name, P):
    """Pose a character once (before the cameras are built) and read off where its eyes end up."""
    pose(name, P)
    CH[name]['J']['root'].rotation_euler = (0, 0, R(P.get('yaw', 0.0)))
    bpy.context.view_layer.update()
    e = eyes_pt(name)
    park(name)
    return e


def build_cameras():
    sci_e = landmark('sci1', dict(loc=tuple(SCI_DESK), yaw=0))
    you_e = landmark(YOU, dict(loc=tuple(HERO), yaw=-8))
    M = DESK + V3(0, 0.085, 1.86)                       # the vertical monitor's centre
    # SCENE 1 - the discovery: frame 1 is the monitor (his photo; the pattern appearing)
    camera_shot('monitor', 30, [(0, V3(M.x + 0.45, M.y - 2.05, 1.86)), (1, V3(M.x + 0.2, M.y - 1.2, 1.78))],
                [(0, M + V3(0, 0, -0.02)), (1, V3(M.x, M.y, 1.6))], fstop=3.5)
    camera_shot('eyes', 55, [(0, sci_e + V3(0.07, 0.6, 0.01)), (1, sci_e + V3(0.05, 0.47, 0.0))],
                [(0, sci_e), (1, sci_e + V3(0.0, 0.0, 0.002))], fstop=2.0)
    camera_shot('look', 28, [(0, V3(M.x + 0.22, M.y - 0.22, 1.63)), (1, V3(M.x + 0.18, M.y - 0.3, 1.64))],
                [(0, sci_e + V3(0, 0, -0.02)), (0.55, sci_e + V3(0.05, -0.4, 0.0)), (1, HERO + V3(0, 0, 1.68))], fstop=2.0)
    # SCENE 2 - the timeline across the lab
    F = FACI
    camera_shot('timeline', 16, [(0, F + V3(-14.0, 30.6, 1.5)), (1, F + V3(-6.0, 31.4, 1.9))],
                [(0, F + V3(-6.0, 37.0, 8.5)), (1, F + V3(4.0, 37.0, 8.5))], fstop=60, ease=False)
    camera_shot('spike', 24, [(0, F + V3(1.0, 30.0, 7.2)), (1, F + V3(3.5, 34.2, 8.5))],
                [(0, F + V3(3.6, 37.0, 8.7)), (1, F + V3(4.05, 37.0, 8.6))], fstop=60, lenses=[(0, 24), (1, 22)], ease='EASE_IN')
    camera_shot('compare', 26, [(0, F + V3(-4.3, 31.9, 1.75)), (1, F + V3(-4.75, 32.35, 1.72))],
                [(0, F + V3(-6.15, 34.0, 1.45)), (1, F + V3(-6.1, 34.0, 1.45))], fstop=3.5)
    # SCENE 3 - Earth, deep space, the scientists watching
    P = SIG_P
    side = SIG_N.cross(SUN_SPACE).normalized()
    nd = (SIG_N * 0.45 + SUN_SPACE).normalized()          # a point on the daylit side, east of the signal's landing
    look_pt = SPACE + (SIG_N * 0.8 + SUN_SPACE * 0.6).normalized() * RE
    camera_shot('earth', 22, [(0, SPACE + nd * (RE + 46.0) + side * 14.0), (1, SPACE + nd * (RE + 40.0) + side * 10.0)],
                [(0, look_pt), (1, look_pt + SIG_N * 1.0)], fstop=200, ease=False)
    perp = SIG_DIR.cross(SIG_N).normalized()
    camera_shot('deepspace', 26, [(0, P + SIG_DIR * 110.0 + perp * 18.0), (1, P + SIG_DIR * 900.0 + perp * 95.0)],
                [(0, SPACE), (1, SPACE)], fstop=200, lenses=[(0, 26), (1, 22)], ease='EASE_IN_OUT')
    camera_shot('watch', 35, [(0, F + V3(-0.9, 50.6, 1.66)), (1, F + V3(-0.75, 49.7, 1.64))],
                [(0, F + V3(-0.6, 47.6, 1.55)), (1, F + V3(-0.55, 47.6, 1.55))], fstop=2.8)
    # SCENE 4 - the twist: the signal reverses; one dive from space to him
    camera_shot('reverse', 26, [(0, P + SIG_DIR * 160.0 + perp * 150.0), (1, P + SIG_DIR * 140.0 + perp * 130.0)],
                [(0, P + SIG_DIR * 60.0), (1, P + SIG_DIR * 40.0)], fstop=200, ease=False)
    camera_shot('dive', 30, [(0, P + SIG_N * 260.0 + perp * 30.0), (1, P + SIG_N * 7.0 + perp * 0.3)],
                [(0, P), (1, P)], fstop=200, ease='EASE_IN')
    H = HERO
    camera_shot('city', 24, [(0, H + V3(25.0, -35.0, 720.0)), (1, H + V3(5.0, -4.5, 52.0))],
                [(0, H + V3(0, 0, 20.3)), (1, H + V3(0, 0, 20.3))], fstop=200, ease='EASE_IN')
    camera_shot('inside', 24, [(0, H + V3(2.4, -1.4, 18.6)), (1, H + V3(1.1, -0.7, 5.2))],
                [(0, H + V3(0, 0.2, 0.0)), (1, H + V3(0, 0.2, 0.6))], fstop=60, ease='EASE_OUT')
    camera_shot('turn', 18, [(0, H + V3(0.45, -2.2, 1.85)), (1, H + V3(0.4, -1.8, 1.82))],
                [(0, F + V3(-0.6, 17.1, 1.45)), (1, F + V3(-0.6, 17.1, 1.5))], fstop=4.0)
    # SCENE 5 - the payoff
    d = fwd(-8)
    camera_shot('face', 50, [(0, you_e + d * 0.95 + V3(-0.3, 0, -0.03)), (1, you_e + d * 0.8 + V3(-0.25, 0, -0.02))],
                [(0, you_e + V3(0, 0, -0.03)), (1, you_e + V3(0, 0, -0.02))], fstop=2.2)
    camera_shot('symbol', 30, [(0, M + V3(0.25, -1.65, -0.1)), (1, M + V3(0.05, -0.8, -0.05))],
                [(0, M + V3(0, 0, -0.2)), (1, M + V3(0, 0, -0.32))], fstop=4.0, ease='EASE_IN')
    camera_shot('step', 30, [(0, H + V3(0.9, 0.5, 1.62)), (1, H + V3(0.8, 0.8, 1.6))],
                [(0, SCI_TWIST + V3(0, 0.3, 1.35)), (1, SCI_TWIST + V3(0, 0.6, 1.4))], fstop=3.2)
    camera_shot('push', 40, [(0, you_e + d * 1.5 + V3(-0.15, 0, -0.02)), (1, you_e + d * 0.42 + V3(-0.04, 0, 0.0))],
                [(0, you_e + V3(0, 0, -0.04)), (1, you_e)], fstop=2.2, lenses=[(0, 40), (1, 60)], ease='EASE_IN')


def SV(key, v):
    for s in SHOTVAL.get(key, []):
        s.default_value = v


def set_img(mat, name):
    img = teximg(name)
    nt = MAT[mat].node_tree
    for nn in ('Img', 'Img2'):
        if nt.nodes[nn].image != img:
            nt.nodes[nn].image = img


def pulse_33(t, rate=0.8):
    """The signal's rhythm in time: three short pulses and one long one per cycle (0..1)."""
    u = (t * rate) % 1.0
    v = 0.0
    for c in (0.06, 0.19, 0.32):
        v = max(v, math.exp(-((u - c) / 0.025) ** 2))
    if 0.48 < u < 0.7:
        v = max(v, 1.0)
    return v


def flicker(t):
    """Failing lights: random drops and stutters from 25.9 s."""
    if t < 25.9:
        return 1.0
    k = int(t * 22)
    r = ((k * 7919) % 101) / 100.0
    base = 0.55 - 0.25 * ramp(t, 25.9, 28.2)
    return base * (0.15 if r < 0.3 else (0.6 if r < 0.55 else 1.0))


def beam_phase(t):
    """Inward along the beam until 17.55 s, frozen until 17.8 s, then outward (the signal changes direction)."""
    return -1.1 * min(t, 17.55) + 1.6 * max(0.0, t - 17.8)


def update_world(t, shot):
    S = SETS
    SV('gtime', t)
    lab = shot not in ('earth', 'deepspace', 'reverse', 'dive', 'city')
    # the lead scientist's monitor: his data, the pattern appears at 0.15 s, the symbol at 25.4 s
    set_img('scr_mon', 'symbol2' if t >= 25.4 else 'sigmon_b')
    S['mon_portrait'].hide_render = t >= 25.4 or not lab
    SV('g_mon', 0.9 if (t < 0.3 or 25.35 <= t < 25.6 or 27.0 <= t < 27.1) else 0.0)
    fl = flicker(t)
    SV('mon_e', 1.0 * (0.6 + 0.4 * fl) * (1.0 + 0.6 * pulse_33(t) * (t < 4.0)))
    S['mon_light'].data.energy = 60.0 * (0.6 + 0.4 * fl)
    # the giant display and the console screens switch to SOURCE: SUBJECT 001 once the signal reverses
    set_img('scr_big', 'sigmap' if t < 21.3 else 'source')
    set_img('scr_cons', 'dis_data' if t < 21.3 else 'source')
    SV('g_big', 0.6 if 14.8 <= t < 15.0 else 0.0)
    SV('g_cons', 0.5 if 21.3 <= t < 21.5 else 0.0)
    # the hologram turns; the timeline flashes at the instant
    S['holo'].rotation_euler = (R(12), 0, t * 0.3)
    SV('holo_e', 3.0 * fl * (0.45 if t >= 21.3 else 1.0))
    SV('tl_e', 3.0)
    SV('tl_flash', 22.0 * math.exp(-((t - 7.3) / 0.14) ** 2) + 4.0 * pulse_33(t - 7.3) * (t > 7.3))
    for lt in S['faci_tops']:
        lt.data.energy = 1800.0 * fl * (0.75 if t >= 22.8 else 1.0)
    if S.get('holo_light'):
        S['holo_light'].data.energy = 2500.0 * fl
    # the signal
    SV('beam_t', beam_phase(t))
    SV('beam_dir', 1.0)
    if shot in ('earth', 'deepspace', 'reverse', 'dive'):
        SV('beam_e', 7.0 * (0.4 + 0.6 * ramp(t, 10.0, 10.6)) * (0.35 if 17.55 <= t < 17.8 else 1.0))
    elif shot == 'city':
        SV('beam_e', 6.0)
    else:
        SV('beam_e', (0.0 if t < 21.0 else 5.0 * (1.0 - 0.55 * ramp(t, 22.6, 23.4))) * (0.5 + 0.5 * fl))
    S['column'].hide_render = t < 21.0 or not lab
    p = pulse_33(t)
    flare = 3.0 + 5.0 * p
    if 17.55 <= t < 17.95:
        flare = 40.0 * math.exp(-((t - 17.7) / 0.08) ** 2) + 4.0
    elif t >= 17.95:
        flare = 8.0 + 8.0 * p
    SV('flare_e', flare)
    S['clouds'].rotation_euler = (0, 0, t * 0.004)
    S['ext_beam'].hide_render = shot != 'city'
    S['roof_glow'].color = (1.2 + 0.8 * p, 0, 0, 1)
    # rings of light across the floor around him, from 21 s
    for k, rg in enumerate(S['rings']):
        if t < 21.0 or not lab:
            rg.color = (0, 0, 0, 1)
            continue
        r = ((t - 21.0) * 2.6 + k * 1.6) % 6.4 + 0.25
        rg.scale = (r, r, 1)
        rg.color = ((1.0 - r / 6.65) ** 1.5 * (0.6 + 0.6 * p) * (0.5 + 0.5 * fl) * (1.0 - 0.5 * ramp(t, 23.0, 24.0)), 0, 0, 1)
    S['hero_light'].data.energy = (0.0 if t < 21.0 else 5.0 + 7.0 * p) * (0.5 + 0.5 * fl)


def animate(t, shot):
    for nm in [YOU] + list(HEROES):
        park(nm)
    fn = CHOR.get(shot)
    if fn is not None:
        fn(t, shot)
    else:
        hide_phone()
    fp = CHOR_PEOPLE.get(shot)
    if fp is not None:
        fp(t, shot)
    update_world(t, shot)

# ============================================================================
# Materials
# ============================================================================
def V_(nt, m, key, v):
    """A Value node registered under `key` (animated per shot / per frame through SHOTVAL)."""
    s = value(nt, key, v)
    register_value(m, key, key)
    return s


def screen_mat(name, tex, gkey, strength, skey=None, overlay=None, live=False, ekey=None):
    """An LED / LCD screen: emissive image, faint scanlines, horizontal-band glitch (gkey), TV static (skey), an
    optional RGBA overlay (HUD) and an optional red "LIVE" wash (live)."""
    m, nt, out = new_mat(name)
    uv = nd(nt, 'ShaderNodeTexCoord').outputs['UV']
    s = sep(nt, uv)
    g = V_(nt, m, gkey, 0.0)
    tt = V_(nt, m, 'gtime', 0.0)
    band = mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', s.outputs['Y'], 26.0))
    bt = mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', tt, 12.0))
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=comb(nt, band, bt, 0.0))
    sel = mth(nt, 'GREATER_THAN', sep(nt, wn.outputs['Color']).outputs['X'], 0.55)
    off = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'SUBTRACT', wn.outputs['Value'], 0.5), g), mth(nt, 'MULTIPLY', sel, 0.5))
    u2 = mth(nt, 'ADD', s.outputs['X'], off)
    img = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND', Vector=comb(nt, u2, s.outputs['Y'], 0.0))
    img.name = 'Img'
    col = img.outputs['Color']
    # chromatic split while glitching: shift red one way
    img2 = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND',
              Vector=comb(nt, mth(nt, 'ADD', u2, mth(nt, 'MULTIPLY', g, 0.012)), s.outputs['Y'], 0.0))
    img2.name = 'Img2'
    sp = nd(nt, 'ShaderNodeSeparateColor', Color=col)
    sp2 = nd(nt, 'ShaderNodeSeparateColor', Color=img2.outputs['Color'])
    col = nd(nt, 'ShaderNodeCombineColor', Red=sp2.outputs['Red'], Green=sp.outputs['Green'], Blue=sp.outputs['Blue']).outputs[0]
    if overlay:
        ov = nd(nt, 'ShaderNodeTexImage', p_image=teximg(overlay), p_interpolation='Linear', p_extension='EXTEND', Vector=uv)
        col = mixc(nt, ov.outputs['Alpha'], col, ov.outputs['Color'])
    if skey:
        st = V_(nt, m, skey, 0.0)
        wn2 = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D',
                 Vector=comb(nt, mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', s.outputs['X'], 320.0)),
                             mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', s.outputs['Y'], 180.0)), mth(nt, 'MULTIPLY', tt, 30.0)))
        col = mixc(nt, st, col, wn2.outputs['Color'])
    if live:
        lv = V_(nt, m, 'live', 0.0)
        red = mixc(nt, 0.5, col, (1.0, 0.1, 0.08, 1))
        col = mixc(nt, mth(nt, 'MULTIPLY', lv, 0.35), col, red)
    lines = mth(nt, 'MULTIPLY_ADD', mth(nt, 'SINE', mth(nt, 'MULTIPLY', s.outputs['Y'], 1400.0)), 0.07, 0.93)
    strength = V_(nt, m, ekey, strength) if ekey else strength
    e = nd(nt, 'ShaderNodeEmission', Color=col, Strength=mth(nt, 'MULTIPLY', lines, strength))
    gl_ = nd(nt, 'ShaderNodeBsdfGlossy', Roughness=0.08, Color=(0.04, 0.04, 0.045, 1))
    ad = nd(nt, 'ShaderNodeAddShader')
    nt.links.new(e.outputs[0], ad.inputs[0])
    nt.links.new(gl_.outputs[0], ad.inputs[1])
    nt.links.new(ad.outputs[0], out.inputs['Surface'])
    MAT[name] = m
    return m


def glow_img(name, tex, strength, alpha=False, key=None):
    m, nt, out = new_mat(name)
    t = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND')
    if key:
        strength = mth(nt, 'MULTIPLY', V_(nt, m, key, 1.0), strength)
    e = nd(nt, 'ShaderNodeEmission', Color=t.outputs['Color'], Strength=strength)
    if alpha:
        tr = nd(nt, 'ShaderNodeBsdfTransparent')
        mx = nd(nt, 'ShaderNodeMixShader', Fac=t.outputs['Alpha'])
        nt.links.new(tr.outputs[0], mx.inputs[1])
        nt.links.new(e.outputs[0], mx.inputs[2])
        nt.links.new(mx.outputs[0], out.inputs['Surface'])
    else:
        nt.links.new(e.outputs[0], out.inputs['Surface'])
    MAT[name] = m
    return m


def future_facade(name, glass, frame, mull=1.6, floor=4.2, band=(0.55, 0.8, 1.0), lit=0.22, stone=False):
    """Curtain-wall towers: glass between mullions and floor slabs, a glowing band every few floors, some lit windows."""
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    s_ = sep(nt, oc)
    h = mth(nt, 'ADD', s_.outputs['X'], s_.outputs['Y'])
    z = s_.outputs['Z']
    u = mth(nt, 'FRACT', mth(nt, 'DIVIDE', h, mull))
    v = mth(nt, 'FRACT', mth(nt, 'DIVIDE', z, floor))
    fw = 0.22 if stone else 0.06
    pane = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', u, fw), mth(nt, 'LESS_THAN', u, 1 - fw)),
               mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', v, 0.16 if stone else 0.1), mth(nt, 'LESS_THAN', v, 0.92)))
    cell = comb(nt, mth(nt, 'FLOOR', mth(nt, 'DIVIDE', h, mull)), mth(nt, 'FLOOR', mth(nt, 'DIVIDE', z, floor)), 0.0)
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=cell)
    gcol = mixc(nt, mth(nt, 'MULTIPLY', wn.outputs['Value'], 0.6), rgba(glass), rgba([min(1, c * 1.6) for c in glass]))
    col = mixc(nt, pane, rgba(frame), gcol)
    roof = mth(nt, 'GREATER_THAN', mth(nt, 'ABSOLUTE', sep(nt, nd(nt, 'ShaderNodeNewGeometry').outputs['Normal']).outputs['Z']), 0.5)
    col = mixc(nt, roof, col, (0.28, 0.28, 0.3, 1))
    pane = mth(nt, 'MULTIPLY', pane, mth(nt, 'SUBTRACT', 1.0, roof))
    rough = mth(nt, 'ADD', mth(nt, 'MULTIPLY', pane, -0.6), 0.7)
    p = principled(nt, out, **{'Base Color': col, 'Roughness': rough, 'Metallic': mth(nt, 'MULTIPLY', pane, 0.0 if stone else 0.6),
                               'Specular IOR Level': 0.6})
    fl = mth(nt, 'FLOOR', mth(nt, 'DIVIDE', z, floor))
    bandm = mth(nt, 'MULTIPLY', mth(nt, 'LESS_THAN', mth(nt, 'MODULO', fl, 6.0), 0.5), mth(nt, 'LESS_THAN', v, 0.08))
    on = mth(nt, 'MULTIPLY', pane, mth(nt, 'GREATER_THAN', sep(nt, wn.outputs['Color']).outputs['Y'], 1 - lit))
    em = mixc(nt, bandm, (1.0, 0.85, 0.65, 1), rgba(band))
    nt.links.new(em, p.inputs['Emission Color'])
    lv = V_(nt, m, 'citylit', 1.0)
    nt.links.new(mth(nt, 'MULTIPLY', mth(nt, 'ADD', mth(nt, 'MULTIPLY', bandm, 6.0), mth(nt, 'MULTIPLY', on, 1.4)), lv), p.inputs['Emission Strength'])
    MAT[name] = m



def panel_metal(name, base, size=(1.2, 1.2), rough=0.35):
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    s_ = sep(nt, oc)
    hx = mth(nt, 'ADD', s_.outputs['X'], s_.outputs['Y'])
    a = mth(nt, 'FRACT', mth(nt, 'DIVIDE', hx, size[0]))
    b = mth(nt, 'FRACT', mth(nt, 'DIVIDE', s_.outputs['Z'], size[1]))
    seam = mth(nt, 'MAXIMUM', mth(nt, 'LESS_THAN', a, 0.012), mth(nt, 'LESS_THAN', b, 0.012))
    cell = comb(nt, mth(nt, 'FLOOR', mth(nt, 'DIVIDE', hx, size[0])), mth(nt, 'FLOOR', mth(nt, 'DIVIDE', s_.outputs['Z'], size[1])), 0.0)
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=cell).outputs['Value']
    col = mixc(nt, mth(nt, 'MULTIPLY', wn, 0.35), rgba(base), rgba([c * 1.4 for c in base]))
    col = mixc(nt, seam, col, (0.005, 0.005, 0.006, 1))
    principled(nt, out, **{'Base Color': col, 'Metallic': 0.75, 'Roughness': mth(nt, 'ADD', rough, mth(nt, 'MULTIPLY', wn, 0.15))})
    MAT[name] = m


def glass_window_material():
    m, nt, out = new_mat('window_glass')
    lw = nd(nt, 'ShaderNodeLayerWeight', Blend=0.25)
    tp = nd(nt, 'ShaderNodeBsdfTransparent', Color=(0.96, 0.98, 0.98, 1))
    gl = nd(nt, 'ShaderNodeBsdfGlossy', Roughness=0.02)
    mx = nd(nt, 'ShaderNodeMixShader', Fac=mth(nt, 'MULTIPLY_ADD', lw.outputs['Fresnel'], 0.6, 0.04))
    nt.links.new(tp.outputs[0], mx.inputs[1])
    nt.links.new(gl.outputs[0], mx.inputs[2])
    nt.links.new(mx.outputs[0], out.inputs['Surface'])
    MAT['window_glass'] = m




def sph_uv(nt):
    """Equirectangular lookup from object coordinates (longitude = atan2(y, x), latitude = asin(z))."""
    oc = nd(nt, 'ShaderNodeTexCoord').outputs['Object']
    n = nd(nt, 'ShaderNodeVectorMath', p_operation='NORMALIZE', Vector=oc).outputs['Vector']
    sp = sep(nt, n)
    u = mth(nt, 'ADD', mth(nt, 'DIVIDE', mth(nt, 'ARCTAN2', sp.outputs['Y'], sp.outputs['X']), 2 * math.pi), 0.5)
    v = mth(nt, 'ADD', mth(nt, 'DIVIDE', mth(nt, 'ARCSINE', sp.outputs['Z']), math.pi), 0.5)
    return comb(nt, u, v, 0.0)


def glow_add(nt, out, color, strength):
    """Additive glow: a transparent surface plus emission (light passes through; the glow adds on top)."""
    tr = nd(nt, 'ShaderNodeBsdfTransparent')
    e = nd(nt, 'ShaderNodeEmission', Color=color, Strength=strength)
    ad = nd(nt, 'ShaderNodeAddShader')
    nt.links.new(tr.outputs[0], ad.inputs[0])
    nt.links.new(e.outputs[0], ad.inputs[1])
    nt.links.new(ad.outputs[0], out.inputs['Surface'])


def attr(nt, name):
    return nd(nt, 'ShaderNodeAttribute', p_attribute_type='OBJECT', p_attribute_name=name).outputs['Fac']


def part3_materials():
    # Earth from orbit
    m, nt, out = new_mat('earth')
    uv = sph_uv(nt)
    tx = nd(nt, 'ShaderNodeTexImage', p_image=teximg('earth'), p_interpolation='Cubic', p_extension='REPEAT', Vector=uv)
    sc = nd(nt, 'ShaderNodeSeparateColor', Color=tx.outputs['Color'])
    ocean = mth(nt, 'GREATER_THAN', sc.outputs['Blue'], mth(nt, 'MULTIPLY', sc.outputs['Red'], 1.6))
    principled(nt, out, **{'Base Color': tx.outputs['Color'], 'Roughness': mth(nt, 'SUBTRACT', 0.85, mth(nt, 'MULTIPLY', ocean, 0.55)),
                           'Specular IOR Level': mth(nt, 'ADD', 0.2, mth(nt, 'MULTIPLY', ocean, 0.5))})
    MAT['earth'] = m
    m, nt, out = new_mat('clouds')
    tx = nd(nt, 'ShaderNodeTexImage', p_image=teximg('clouds'), p_interpolation='Cubic', p_extension='REPEAT', Vector=sph_uv(nt))
    principled(nt, out, **{'Base Color': (0.95, 0.96, 0.98, 1), 'Roughness': 0.9, 'Alpha': mth(nt, 'MULTIPLY', tx.outputs['Color'], 0.92)})
    MAT['clouds'] = m
    m, nt, out = new_mat('atmo')
    lw = nd(nt, 'ShaderNodeLayerWeight', Blend=0.5)
    rim = mth(nt, 'POWER', lw.outputs['Facing'], 3.0)
    glow_add(nt, out, (0.32, 0.6, 1.0, 1), mth(nt, 'MULTIPLY', mth(nt, 'POWER', lw.outputs['Facing'], 5.0), 1.6))
    MAT['atmo'] = m
    m, nt, out = new_mat('moon')
    n = noise(nt, 6.0, 6.0, 0.6, vec=obj_coord(nt))
    principled(nt, out, **{'Base Color': mixc(nt, n, (0.22, 0.22, 0.22, 1), (0.55, 0.54, 0.52, 1)), 'Roughness': 0.95})
    MAT['moon'] = m
    m, nt, out = new_mat('stars')
    tx = nd(nt, 'ShaderNodeTexImage', p_image=teximg('stars'), p_interpolation='Closest', p_extension='REPEAT', Vector=sph_uv(nt))
    e = nd(nt, 'ShaderNodeEmission', Color=tx.outputs['Color'], Strength=V_(nt, m, 'stars_e', 2.0))
    nt.links.new(e.outputs[0], out.inputs['Surface'])
    MAT['stars'] = m
    m, nt, out = new_mat('flare')
    lw = nd(nt, 'ShaderNodeLayerWeight', Blend=0.5)
    core = mth(nt, 'POWER', mth(nt, 'SUBTRACT', 1.0, lw.outputs['Facing']), 2.0)
    glow_add(nt, out, (0.55, 0.82, 1.0, 1), mth(nt, 'MULTIPLY', core, V_(nt, m, 'flare_e', 0.0)))
    MAT['flare'] = m
    # the signal: the 3 + 1 pattern runs along each beam (object property 'length'; 'beam_dir' +1 = outward)
    m, nt, out = new_mat('beam')
    z = sep(nt, nd(nt, 'ShaderNodeTexCoord').outputs['Object']).outputs['Z']
    period = attr(nt, 'period')
    ph = mth(nt, 'SUBTRACT', mth(nt, 'DIVIDE', z, period), mth(nt, 'MULTIPLY', V_(nt, m, 'beam_t', 0.0), V_(nt, m, 'beam_dir', 1.0)))
    strip = nd(nt, 'ShaderNodeTexImage', p_image=teximg('sigstrip'), p_interpolation='Linear', p_extension='REPEAT',
               Vector=comb(nt, mth(nt, 'FRACT', ph), 0.5, 0.0))
    fade = mth(nt, 'SUBTRACT', 1.0, mth(nt, 'POWER', mth(nt, 'DIVIDE', z, attr(nt, 'length')), 0.6), clamp=True)
    lw = nd(nt, 'ShaderNodeLayerWeight', Blend=0.4)
    soft = mth(nt, 'POWER', mth(nt, 'SUBTRACT', 1.0, lw.outputs['Facing']), 1.5)
    k = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'ADD', 0.12, strip.outputs['Color']), fade), soft)
    glow_add(nt, out, (0.38, 0.72, 1.0, 1), mth(nt, 'MULTIPLY', k, V_(nt, m, 'beam_e', 0.0)))
    MAT['beam'] = m
    # rings on the floor around him: brightness from the object colour (set per frame)
    m, nt, out = new_mat('ring')
    oi = nd(nt, 'ShaderNodeObjectInfo')
    glow_add(nt, out, (0.35, 0.7, 1.0, 1), mth(nt, 'MULTIPLY', sep(nt, oi.outputs['Color']).outputs['X'], 8.0))
    MAT['ring'] = m
    # the holographic Earth in the hall
    m, nt, out = new_mat('holo_earth')
    tx = nd(nt, 'ShaderNodeTexImage', p_image=teximg('earth'), p_interpolation='Linear', p_extension='REPEAT', Vector=sph_uv(nt))
    land = mth(nt, 'GREATER_THAN', sep(nt, tx.outputs['Color']).outputs['X'], 0.08)
    lw = nd(nt, 'ShaderNodeLayerWeight', Blend=0.5)
    k = mth(nt, 'ADD', mth(nt, 'MULTIPLY', land, 0.9), mth(nt, 'MULTIPLY', mth(nt, 'POWER', lw.outputs['Facing'], 2.0), 1.4))
    glow_add(nt, out, (0.32, 0.68, 1.0, 1), mth(nt, 'MULTIPLY', mth(nt, 'ADD', k, 0.08), V_(nt, m, 'holo_e', 3.0)))
    MAT['holo_earth'] = m
    # the holographic timeline ribbon (black = clear)
    m, nt, out = new_mat('timeline_holo')
    tx = nd(nt, 'ShaderNodeTexImage', p_image=teximg('timeline3'), p_interpolation='Linear', p_extension='EXTEND')
    glow_add(nt, out, tx.outputs['Color'], mth(nt, 'ADD', V_(nt, m, 'tl_e', 3.0), V_(nt, m, 'tl_flash', 0.0)))
    MAT['timeline_holo'] = m
    screen_mat('scr_mon', 'sigmon_a', 'g_mon', 1.4, ekey='mon_e')
    screen_mat('scr_big', 'sigmap', 'g_big', 2.0)
    screen_mat('scr_cons', 'dis_data', 'g_cons', 1.5)
    screen_mat('scr_compare', 'compare', 'g_cons', 1.6)
    glow_img('portrait_mon', 'portrait', 1.0, key='mon_e')


