    emission_mat('led_blue_dim', (0.25, 0.5, 1.0), 1.6)
    emission_mat('led_violet', (0.55, 0.32, 1.0), 6.0)
    for nm, a, st in (('holo', 0.35, 5.0), ('holo_beam', 0.88, 0.7)):
        m, nt, out = new_mat(nm)
        tr = nd(nt, 'ShaderNodeBsdfTransparent')
        e = nd(nt, 'ShaderNodeEmission', Color=(0.35, 0.68, 1.0, 1), Strength=V_(nt, m, nm + '_e', st))
        mx = nd(nt, 'ShaderNodeMixShader', Fac=a)
        nt.links.new(e.outputs[0], mx.inputs[1])
        nt.links.new(tr.outputs[0], mx.inputs[2])
        nt.links.new(mx.outputs[0], out.inputs['Surface'])
        m.blend_method = 'BLEND'
        MAT[nm] = m
    m, nt, out = new_mat('glass_room')
    tr = nd(nt, 'ShaderNodeBsdfTransparent', Color=(0.85, 0.9, 0.95, 1))
    gl_ = nd(nt, 'ShaderNodeBsdfGlossy', Roughness=0.03, Color=(1, 1, 1, 1))
    fr = nd(nt, 'ShaderNodeLayerWeight', Blend=0.25)
    mx = nd(nt, 'ShaderNodeMixShader', Fac=mth(nt, 'MULTIPLY_ADD', fr.outputs['Fresnel'], 0.6, 0.06))
    nt.links.new(tr.outputs[0], mx.inputs[1])
    nt.links.new(gl_.outputs[0], mx.inputs[2])
    nt.links.new(mx.outputs[0], out.inputs['Surface'])
    MAT['glass_room'] = m
    part3_materials()
    particle_materials()


