def cfg(light, grade, groups, **kw):
    d = dict(light=light, grade=grade, groups=groups, exposure=0.0, hide=[])
    d.update(kw)
    return d


L_STREET = dict(sky=((0.62, 0.66, 0.74), (0.30, 0.36, 0.5), 0.8), sun=(16, -120, 1.4, (0.85, 0.9, 1.0)), glow=(0.15, (0.7, 0.75, 1.0)),
                clouds=0.85, mist=(40, 600), fog=(0.28, (0.55, 0.6, 0.7)))
L_NIGHT = dict(sky=((0.10, 0.12, 0.2), (0.02, 0.03, 0.07), 0.6), sun=(1, -95, 0.0, (1, 1, 1)), glow=(0.15, (0.5, 0.4, 0.9)),
               clouds=0.4, mist=(40, 700), fog=(0.18, (0.12, 0.14, 0.24)))
L_DARK = dict(sky=((0.05, 0.06, 0.09), (0.02, 0.02, 0.04), 0.12), sun=(40, 0, 0.0, (1, 1, 1)), glow=(0.0, (0, 0, 0)),
              clouds=0.0, mist=(1e4, 10), fog=(0.0, (0, 0, 0)))
GRADE.update({
    'steel':  ((0.985, 1.0, 1.03), (0.97, 0.99, 1.04), (0.98, 1.0, 1.05), 0.88),
    'violet': ((1.0, 0.98, 1.04), (0.98, 0.98, 1.05), (1.0, 0.98, 1.05), 0.92),
})
# kerb trees and lamps that would block the opening's view of the giant screen
